// agree rather than one depending on the other.
// ---------------------------------------------------------------- packages
func (q *Queries) ListPlans(ctx context.Context) ([]Plan, error) {
	rows, err := q.db.Query(ctx, listPlans)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Plan{}
	for rows.Next() {
		var i Plan
		if err := rows.Scan(
			&i.ID,
			&i.Key,
			&i.Name,
			&i.MonthlyPriceIdr,
			&i.TokenQuota,
			&i.MaxAgents,
			&i.MaxIntegrations,
			&i.MaxMembers,
			&i.IsTrial,
			&i.SortOrder,
			&i.CreatedAt,
			&i.DailyCostMicros,
			&i.PeriodDays,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

