const setInvoicePayment = `-- name: SetInvoicePayment :one
UPDATE billing_invoices
SET provider = $1,
    provider_reference = $2,
    payment_instructions = $3,
    expires_at = $4,
    attempts = $5,
    last_error = $6,
    updated_at = now()
WHERE id = $7 AND workspace_id = $8
RETURNING id, workspace_id, subscription_id, provider, provider_reference, amount_idr, status, period_start, period_end, paid_at, created_at, updated_at, kind, token_amount, payment_instructions, attempts, last_error, expires_at
`

type SetInvoicePaymentParams struct {
	Provider            string
	ProviderReference   string
	PaymentInstructions string
	ExpiresAt           *time.Time
	Attempts            int32
	LastError           string
	ID                  uuid.UUID
	WorkspaceID         uuid.UUID
}

// The routing row is written in the same statement's transaction by the repository, so a
// payment link that exists is a payment link the notification can find.
func (q *Queries) SetInvoicePayment(ctx context.Context, arg SetInvoicePaymentParams) (BillingInvoice, error) {
	row := q.db.QueryRow(ctx, setInvoicePayment,
		arg.Provider,
		arg.ProviderReference,
		arg.PaymentInstructions,
		arg.ExpiresAt,
		arg.Attempts,
		arg.LastError,
		arg.ID,
		arg.WorkspaceID,
	)
	var i BillingInvoice
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.SubscriptionID,
		&i.Provider,
		&i.ProviderReference,
		&i.AmountIdr,
		&i.Status,
		&i.PeriodStart,
		&i.PeriodEnd,
		&i.PaidAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Kind,
		&i.TokenAmount,
		&i.PaymentInstructions,
		&i.Attempts,
		&i.LastError,
		&i.ExpiresAt,
	)
	return i, err
}

const setInvoiceSettlement = `-- name: SetInvoiceSettlement :one
UPDATE billing_invoices
SET status = $1,
    paid_at = $2,
    updated_at = now()
WHERE id = $3
  AND workspace_id = $4
  AND status = 'pending'
RETURNING id, workspace_id, subscription_id, provider, provider_reference, amount_idr, status, period_start, period_end, paid_at, created_at, updated_at, kind, token_amount, payment_instructions, attempts, last_error, expires_at
`

type SetInvoiceSettlementParams struct {
	Status      string
	PaidAt      *time.Time
	ID          uuid.UUID
	WorkspaceID uuid.UUID
}

// The outcome is written once. The `status = 'pending'` guard is the whole
// idempotency of a replayed webhook: a second delivery updates nothing and the
// caller reads zero rows, so a period cannot be extended twice for one payment.
func (q *Queries) SetInvoiceSettlement(ctx context.Context, arg SetInvoiceSettlementParams) (BillingInvoice, error) {
	row := q.db.QueryRow(ctx, setInvoiceSettlement,
		arg.Status,
		arg.PaidAt,
		arg.ID,
		arg.WorkspaceID,
	)
	var i BillingInvoice
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.SubscriptionID,
		&i.Provider,
		&i.ProviderReference,
		&i.AmountIdr,
		&i.Status,
		&i.PeriodStart,
		&i.PeriodEnd,
		&i.PaidAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Kind,
		&i.TokenAmount,
		&i.PaymentInstructions,
		&i.Attempts,
		&i.LastError,
		&i.ExpiresAt,
	)
	return i, err
}

